// ---------------------------------------------------------------------------
// WF2 · Construir el email de aviso a administración (caso con Gate), en HTML.
// Entrada ($json): la respuesta de GET /gate-avisos/{oportunidad_id}.
// Salida: { asunto, html, telegram, enlace_formulario }.
// Determinista: ningún LLM toca este texto ni las cifras (D21.6).
// ---------------------------------------------------------------------------

// ---- 1. Atajos a las partes del aviso ---------------------------------------
const a = $json;            // el aviso completo
const c = a.contacto;       // nombre, email, telefono y origen
const r = a.reforma;        // tipo, m2, acabados y cambios estructurales
const p = a.presupuesto;    // fecha, motivo, importes y umbral

// ---- 2. Colores de la empresa (un solo sitio para cambiarlos) ---------------
const AZUL = '#0B3C5D';            // azul marino: cabecera y títulos
const TURQUESA = '#1F8A8A';        // azul verdoso: acentos y franjas
const TURQUESA_CLARO = '#E3F2F1';  // fondo suave de la caja de importes
const FONDO = '#EEF3F6';           // gris azulado alrededor de la tarjeta
const TEXTO = '#1F2933';           // texto principal (casi negro)
const SUAVE = '#5B6B79';           // texto secundario (etiquetas y pie)

// ---- 2b. NUEVO (2026-10-06): enlace al formulario del Gate ------------------
   // Dirección PÚBLICA del formulario de llamadas (dominio fijo de ngrok + ruta "resultado-llamada"; F5, 15/10/2026).
// Constante aquí porque n8n 2.x bloquea por defecto leer variables de entorno
// desde un nodo Code. Si cambia el dominio, se cambia SOLO esta línea.
const FORMULARIO_BASE = 'https://TU-DOMINIO.ngrok-free.dev/form/resultado-llamada';
// "?oportunidad_id=..." rellena el campo con ese Field Name (solo en producción).
// encodeURIComponent prepara el valor para ir dentro de una URL.
const enlace = `${FORMULARIO_BASE}?oportunidad_id=${encodeURIComponent(a.oportunidad_id)}`;

// ---- 3. Seguridad: escapar el texto antes de meterlo en el HTML -------------
// El nombre, el email o las rutas de las fotos los escribió el CLIENTE. Sin
// esto, un "<a href=...>" escrito como nombre se convertiría en un enlace real
// dentro del email (inyección de HTML). esc() cambia los 5 caracteres
// especiales de HTML por su forma inofensiva. String() convierte números a
// texto para poder usar .replace. Cada .replace(/x/g, 'y') cambia TODAS las x.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ---- 4. Formatos españoles (solo para MOSTRAR; aquí no se calcula nada) -----
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
// Números sin ceros sobrantes: 90.0 -> "90", 21.00 -> "21", 8.5 -> "8,5".
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });

// Importe en texto exacto ("87120.00") -> "87.120,00 €"; si falta, un guion.
function dinero(texto) {
  if (texto === null || texto === undefined) return '—';
  return eur.format(Number(texto));
}
// Número en texto ("90.0") -> "90"; si falta, un guion.
function numero(texto) {
  if (texto === null || texto === undefined) return '—';
  return num.format(Number(texto));
}
// Fecha con desfase ("2026-10-03T12:15:00+02:00") -> "03/10/2026, 12:15",
// siempre en hora de Madrid.
function fecha(texto) {
  if (!texto) return '—';
  return new Date(texto).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

// ---- 5. Diccionarios: códigos del backend -> texto legible ------------------
const TIPOS = {
  bano: 'Baño',
  cocina: 'Cocina',
  integral_vivienda: 'Reforma integral de vivienda',
  parcial_acabados: 'Acabados parciales (pintura, electricidad o fontanería)',
};
const ACABADOS = { basico: 'Básico', medio: 'Medio', alto: 'Alto' };
const MOTIVOS = {
  cambios_estructurales: 'Incluye cambios estructurales',
  importe_superior_umbral: 'El importe máximo sin IVA supera el umbral de su categoría',
  ambos: 'Cambios estructurales e importe máximo sin IVA por encima del umbral',
};
const ESTADOS = {
  pendiente_aprobacion: 'Pendiente de llamada',
  visita_agendada: 'Visita acordada',
  perdida: 'Descartada',
  ganada: 'Ganada',
};
const DECISIONES = { visita_acordada: 'Visita acordada', descartar: 'Descartado' };

// "??": si el código no está en el diccionario (un valor nuevo del backend),
// se escribe el código tal cual; si ni siquiera hay código, un guion.
const tipo = TIPOS[r.tipo_reforma] ?? r.tipo_reforma ?? '—';
const acabados = ACABADOS[r.nivel_acabados] ?? r.nivel_acabados ?? '—';
const motivo = MOTIVOS[p.motivo_gate] ?? p.motivo_gate ?? '—';
const estado = ESTADOS[a.estado_oportunidad] ?? a.estado_oportunidad ?? '—';
// true -> "Sí", false -> "No", cualquier otra cosa -> guion.
const cambios = r.incluye_cambios_estructurales === true ? 'Sí'
              : r.incluye_cambios_estructurales === false ? 'No' : '—';

// ---- 6. Piezas de HTML reutilizables ----------------------------------------
// Una fila "etiqueta | valor". El VALOR siempre pasa por esc(), así ningún dato
// puede colarse como HTML. Las etiquetas son textos fijos de este código.
function fila(etiqueta, valor) {
  return `<tr>
    <td style="padding:6px 0;width:42%;color:${SUAVE};font-size:13px;vertical-align:top;">${etiqueta}</td>
    <td style="padding:6px 0;color:${TEXTO};font-size:14px;font-weight:bold;">${esc(valor)}</td>
  </tr>`;
}
// Una sección: título turquesa en mayúsculas, una línea fina y sus filas.
function seccion(titulo, filas) {
  return `<tr><td style="padding:18px 32px 4px;">
    <div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;color:${TURQUESA};font-weight:bold;border-bottom:2px solid ${TURQUESA_CLARO};padding-bottom:6px;margin-bottom:6px;">${titulo}</div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${filas}</table>
  </td></tr>`;
}

// ---- 7. Contenido de cada sección -------------------------------------------
// Contacto (P1 del plan): el de ESTA solicitud, o un aviso si es un lead antiguo.
const filasContacto = c.origen === 'solicitud'
  ? fila('Nombre', c.nombre ?? '—') + fila('Teléfono', c.telefono ?? '—') + fila('Email', c.email ?? '—')
  : fila('Contacto', 'No disponible en esta solicitud (lead anterior al 25/09/2026)');

const filasSolicitud =
  fila('Oportunidad', a.oportunidad_id) +
  fila('Recibida', fecha(a.fecha_solicitud)) +
  fila('Estado', estado);

const filasReforma =
  fila('Tipo', tipo) +
  fila('Superficie', `${numero(r.m2)} m²`) +
  fila('Acabados', acabados) +
  fila('Cambios estructurales', cambios);

const filasPresupuesto =
  fila('Fecha del presupuesto', fecha(p.fecha_presupuesto)) +
  fila('Motivo del Gate', motivo) +
  fila('Horquilla sin IVA', `${dinero(p.importe_min_sin_iva)} – ${dinero(p.importe_max_sin_iva)}`) +
  fila('Umbral vigente (sin IVA)', dinero(p.umbral_gate_vigente));

// Fotos: una fila por ruta ("Foto 1", "Foto 2"...), o "Sin fotos".
// .map transforma cada ruta en una fila; .join('') las pega una tras otra.
const filasFotos = (a.fotos && a.fotos.length)
  ? a.fotos.map((f, i) => fila(`Foto ${i + 1}`, f)).join('')
  : fila('Fotos', 'Sin fotos');

// Caja destacada con la horquilla CON IVA (la cifra principal del caso).
const cajaImportes = `<tr><td style="padding:16px 32px 0;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${TURQUESA_CLARO};border-left:4px solid ${TURQUESA};border-radius:6px;">
    <tr><td style="padding:14px 18px;">
      <div style="font-size:12px;color:${SUAVE};">Horquilla del presupuesto (IVA ${esc(numero(p.iva_pct_aplicado))} % incluido)</div>
      <div style="font-size:22px;font-weight:bold;color:${AZUL};margin-top:4px;">${esc(dinero(p.importe_min_con_iva))} – ${esc(dinero(p.importe_max_con_iva))}</div>
    </td></tr>
  </table>
</td></tr>`;

// NUEVO (2026-10-06): botón al formulario del Gate, SOLO si aún no hay decisión.
// Botón hecho con una tabla (lo único fiable en clientes de correo) y, debajo,
// el enlace en texto por si el cliente de correo no muestra bien el botón.
// esc(enlace): dentro de un atributo HTML, un "&" debe escribirse "&amp;".
const botonFormulario = a.decision ? '' : `<tr><td style="padding:16px 32px 0;">
  <table role="presentation" cellpadding="0" cellspacing="0"><tr>
    <td style="background:${AZUL};border-radius:6px;">
      <a href="${esc(enlace)}" style="display:inline-block;padding:12px 22px;color:#FFFFFF;font-size:15px;font-weight:bold;text-decoration:none;">Registrar resultado de la llamada</a>
    </td>
  </tr></table>
  <div style="font-size:12px;color:${SUAVE};margin-top:8px;line-height:1.5;">
    Si el botón no funciona, copia este enlace en el navegador:<br>
    <span style="color:${TURQUESA};word-break:break-all;">${esc(enlace)}</span>
  </div>
</td></tr>`;

// Aviso en ámbar si el caso YA tiene decisión (normalmente no habrá ninguna).
const bannerDecision = a.decision
  ? `<tr><td style="padding:16px 32px 0;">
      <div style="background:#FEF3C7;border-left:4px solid #B45309;border-radius:6px;padding:12px 16px;color:#78350F;font-size:14px;">
        <b>Atención:</b> este caso ya tiene una decisión registrada
        (${esc(DECISIONES[a.decision.decision] ?? a.decision.decision)}, ${esc(fecha(a.decision.fecha_decision))}).
        No hace falta llamar.
      </div>
    </td></tr>`
  : '';

// ---- 8. El email completo ---------------------------------------------------
// Estructura: fondo gris azulado > tarjeta blanca de 600 px > cabecera azul con
// el nombre de la empresa arriba a la izquierda > franja turquesa > contenido.
const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:${FONDO};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${FONDO};padding:24px 0;">
<tr><td align="center">
  <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#FFFFFF;border-radius:8px;font-family:Arial,Helvetica,sans-serif;color:${TEXTO};">

    <tr><td style="background:${AZUL};padding:20px 32px;border-radius:8px 8px 0 0;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
        <td style="color:#FFFFFF;font-size:18px;font-weight:bold;">
          Reformas Integrales Amedida
          <div style="font-size:12px;font-weight:normal;color:#A7D8D6;margin-top:2px;">Aviso interno · Administración</div>
        </td>
        <td align="right" style="vertical-align:top;">
          <span style="background:${TURQUESA};color:#FFFFFF;font-size:12px;font-weight:bold;padding:6px 12px;border-radius:12px;">GATE</span>
        </td>
      </tr></table>
    </td></tr>
    <tr><td style="height:4px;line-height:4px;font-size:0;background:${TURQUESA};">&nbsp;</td></tr>

    <tr><td style="padding:24px 32px 0;">
      <div style="font-size:20px;font-weight:bold;color:${AZUL};">Presupuesto pendiente de llamada</div>
      <p style="font-size:14px;line-height:1.5;margin:8px 0 0;">
        Este presupuesto necesita revisión personal. Llamad al cliente lo antes posible para acordar una visita o descartar el caso.
      </p>
    </td></tr>

    ${bannerDecision}
    ${cajaImportes}
    ${botonFormulario}
    ${seccion('Contacto', filasContacto)}
    ${seccion('Solicitud', filasSolicitud)}
    ${seccion('Reforma', filasReforma)}
    ${seccion('Presupuesto', filasPresupuesto)}
    ${seccion('Fotos', filasFotos)}

    <tr><td style="padding:24px 32px;">
      <div style="border-top:1px solid #E5E9ED;padding-top:12px;font-size:12px;line-height:1.5;color:${SUAVE};">
        Aviso generado automáticamente. Las cifras salen del presupuesto guardado; al cliente no se le ha mostrado ninguna cifra.<br>
        Uso interno: contiene datos personales. No reenviar fuera del equipo.
      </div>
    </td></tr>

  </table>
</td></tr>
</table>
</body></html>`;

// Asunto SIN el nombre del cliente (RGPD: los asuntos se ven en notificaciones).
const asunto = `[Gate] Llamar al cliente · Oportunidad ${a.oportunidad_id} · ${tipo}`;

// ---- 9. Mensaje corto para Telegram (D23) -----------------------------------
// CORREGIDO (2026-10-06): el nodo de Telegram de n8n envía por defecto en modo
// Markdown, donde "_" y "*" abren cursiva o negrita. Un "_" sin cerrar (el de
// "oportunidad_id" en el enlace, o uno en el NOMBRE de un cliente) hacía que
// Telegram rechazara el mensaje entero, en silencio (On Error -> Continue).
// Ahora el nodo usa modo HTML (Parse Mode = HTML) y TODO dato variable pasa por
// esc(): en HTML, Telegram solo trata como especiales <, > y &, y esc() los
// neutraliza. Minimización (RGPD): solo lo necesario para llamar y registrar;
// sin importes ni email del cliente (están en el email).
const lineasContacto = c.origen === 'solicitud'
  ? `${esc(c.nombre ?? '—')}\nTel: ${esc(c.telefono ?? '—')}`
  : 'Contacto no disponible (lead anterior al 25/09/2026)';

// Enlace al formulario como texto pulsable (solo si aún no hay decisión).
// Dentro de href, el enlace también pasa por esc() (un "&" debe ir como "&amp;").
const lineaFormulario = a.decision
  ? ''
  : `👉 <a href="${esc(enlace)}">Registrar el resultado de la llamada</a>\n\n`;

const telegram =
  `🔔 <b>GATE · Llamar al cliente</b>\n\n` +
  `${lineasContacto}\n\n` +
  `Oportunidad ${esc(a.oportunidad_id)} · ${esc(tipo)}\n` +
  `Motivo: ${esc(motivo)}\n\n` +
  lineaFormulario +
  `Detalles completos en el email.`;

// Salida del nodo: asunto y HTML para Gmail, texto para Telegram, y el enlace
// (para poder comprobarlo en la salida del nodo).
return { json: { asunto, html, telegram, enlace_formulario: enlace } };
